async function finish() {
  const frames=await Promise.all(screens.map(([id])=>figma.getNodeByIdAsync(id)));
  if(frames.some(f=>!f || f.type!=='FRAME')) throw Error('TestPilot ZIP을 가져온 원래 Figma 파일에서 실행하세요.');
  let replaced=0;
  for(const [index,frame] of frames.entries()) {
    frame.name='TestPilot / '+screens[index][1];frame.x=5200+index*1560;frame.y=0;
    const icons=frame.findAllWithCriteria({types:['TEXT']}).filter(t=>Object.prototype.hasOwnProperty.call(paths,t.characters.trim()));
    for(const t of icons) {
      const name=t.characters.trim(), parent=t.parent;
      const size=typeof t.fontSize==='number'?t.fontSize:16;
      const color=Array.isArray(t.fills)&&t.fills[0]?.color || {r:.15,g:.19,b:.25};
      const hex='#'+[color.r,color.g,color.b].map(n=>Math.round(n*255).toString(16).padStart(2,'0')).join('');
      const icon=figma.createNodeFromSvg('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 960" width="'+size+'" height="'+size+'"><path fill="'+hex+'" d="'+paths[name]+'"/></svg>');
      icon.name='Icon / '+name; parent.insertChild(parent.children.indexOf(t),icon);
      icon.x=t.x;icon.y=t.y;t.remove();
      if(parent.type==='FRAME'&&parent.children.length===1&&parent.name==='Text'){parent.resize(size,size);parent.name='Icon slot';}
      replaced++;
    }
  }
  figma.viewport.scrollAndZoomIntoView([frames[0]]);
  figma.closePlugin('TestPilot 화면 5개 정렬 · 아이콘 '+replaced+'개 수정');
}
finish().catch(error=>figma.closePlugin(String(error)));

